 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Vikram. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hi Vikram, I'm Emily Gupta. I've been having terrible network issues at my house for the last three days. I can't even make a simple phone call.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am sorry to hear that you are experiencing connectivity problems, Ms. Gupta. I can certainly look into this for you. Before we proceed, could you please provide your account number for verification?",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "customer",
      "text": "Yes, my account number is 63082563.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you. And just to confirm, is your address 132 Station Road?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "That is correct.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am checking the network status in your area. Please hold for a moment.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "I've already waited long enough. I just want my service to work.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I see there are no reported outages in your area, so the issue might be related to your specific connection. Have you tried restarting your device?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Of course I have! I've restarted it five times. My phone number is 91618 05305, and it's not working regardless of where I am in the house.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I understand. I will run a remote diagnostic on your line now. One moment please.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "The diagnostic didn't show any immediate errors. I cannot determine the cause of the problem from here.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "What do you mean you can't determine the cause? This is ridiculous! I'm paying for a service that doesn't work!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I apologize, but without a clear error code, I cannot fix this remotely. You may need to check your hardware.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "My hardware is fine! You are completely useless. I am beyond frustrated with this entire experience!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Is there anything else I can assist you with today? Since we couldn't find a remote fix, I suggest monitoring the connection. Thank you for calling Nimbus Telecom. Goodbye.",
      "tags": [
        "closure"
      ]
    }
  ]
}
